import type { ClaudeAdapter, DraftInput, EditDraft } from "../types";

/**
 * DEMO adapter: deterministic template, NOT generated by Claude. It only reuses verified facts and
 * default CTAs verbatim, so it cannot invent claims either.
 */
const LINES: Record<string, string[]> = {
  calm: ["เช้านี้เริ่มช้าๆ", "กลิ่นกาแฟลอยมาก่อนเลย", "ค่อยๆ ดริปทีละนิด", "แก้วนี้ทำให้คุณ"],
  energetic: ["พร้อมลุยวันใหม่!", "คั่วสดทุกสัปดาห์", "ดริปแล้วไปต่อ", "แก้วนี้ของคุณ"],
  cinematic: ["ทุกเมล็ดมีเรื่องเล่า", "จากเตาคั่ว", "สู่แก้วตรงหน้า", "BALENA"],
  tutorial: ["ขั้นแรก ชั่งกาแฟ", "รินน้ำให้บลูม", "รินต่อเป็นวงช้าๆ", "พร้อมดื่มแล้ว"],
  behind_the_scenes: ["เบื้องหลังที่ร้านเรา", "คั่วเองทุกล็อต", "แพ็กด้วยมือ", "ส่งถึงคุณ"],
};

export class DemoClaudeAdapter implements ClaudeAdapter {
  readonly mode = "demo" as const;

  async draftEdit(input: DraftInput): Promise<EditDraft> {
    const target = Math.max(6, input.brief.targetDurationSec) * 1000;
    const clips = input.clips.slice(0, 6);
    const per = Math.max(1500, Math.floor(target / Math.max(1, clips.length)));
    const plan = clips.map((c) => {
      const len = Math.min(per, c.durationMs);
      const inMs = Math.max(0, Math.floor((c.durationMs - len) / 2 / 100) * 100);
      return { footageId: c.footageId, inMs, outMs: inMs + len };
    });
    const total = plan.reduce((s, c) => s + (c.outMs - c.inMs), 0);
    const lines = LINES[input.brief.style] ?? LINES.calm;
    const slot = Math.floor(total / lines.length);
    const subtitles = lines.map((text, i) => ({
      id: `sub_${i + 1}`,
      startMs: i * slot + 200,
      endMs: (i + 1) * slot - 100,
      text,
    }));
    const productLine = input.product
      ? `${input.product.nameTh ?? input.product.name}${input.product.verifiedFacts[0] ? ` — ${input.product.verifiedFacts[0]}` : ""}`
      : "";
    const cta = input.brand.defaultCtas[0] ?? "";
    const captionTh = [
      "เริ่มเช้าวันใหม่กับกาแฟแก้วโปรด ☕",
      input.brief.purpose ? `วันนี้อยากชวนดู${input.brief.purpose.replace(/^ชวน/, "")}` : "",
      productLine,
      cta,
    ]
      .filter(Boolean)
      .join("\n");
    return {
      clips: plan,
      subtitles,
      captionTh,
      rationale: "Demo template: clips trimmed evenly to the target length; copy reuses only verified facts and default CTAs.",
      generatedBy: "demo_template",
      model: null,
    };
  }
}
